function creerFilePriorite() {
  const elements = [];

  function echanger(i, j) {
    const temp = elements[i];
    elements[i] = elements[j];
    elements[j] = temp;
  }

  function remontrer(idx) {
    while (idx > 0) {
      const parent = Math.floor((idx - 1) / 2);
      if (elements[parent].priorite <= elements[idx].priorite) break;
      echanger(idx, parent);
      idx = parent;
    }
  }

  function descendre(idx) {
    const length = elements.length;
    while (true) {
      const gauche = 2 * idx + 1;
      const droite = 2 * idx + 2;
      let plusPetit = idx;

      if (gauche < length && elements[gauche].priorite < elements[plusPetit].priorite) {
        plusPetit = gauche;
      }
      if (droite < length && elements[droite].priorite < elements[plusPetit].priorite) {
        plusPetit = droite;
      }
      if (plusPetit === idx) break;

      echanger(idx, plusPetit);
      idx = plusPetit;
    }
  }

  function enqueue(valeur, priorite) {
    elements.push({ valeur, priorite });
    remontrer(elements.length - 1);
  }

  function dequeue() {
    if (elements.length === 0) return undefined;
    const min = elements[0];
    const dernier = elements.pop();
    if (elements.length > 0) {
      elements[0] = dernier;
      descendre(0);
    }
    return min.valeur;
  }

  function taille() {
    return elements.length;
  }

  return { enqueue, dequeue, taille };
}
```

