### tache_2a

```javascript
async function chargerEnParallele(urls, chargement) {
  const succes = [];
  const echecs = [];

  const promesses = urls.map(async (url) => {
    try {
      const resultat = await chargement(url);
      succes.push(resultat);
    } catch (e) {
      echecs.push(url);
    }
  });

  await Promise.all(promesses);

  return { succes, echecs };
}
