function creerSubject() {
  const observers = [];

  return {
    next(valeur) {
      observers.forEach(({ next }) => {
        try { next && next(valeur); } catch (e) { /* ignore */ }
      });
    },
    error(err) {
      observers.forEach(({ error }) => {
        try { error && error(err); } catch (e) { /* ignore */ }
      });
    },
    complete() {
      observers.forEach(({ complete }) => {
        try { complete && complete(); } catch (e) { /* ignore */ }
      });
    },
    subscribe({ next, error, complete }) {
      observers.push({ next, error, complete });
