function remplirMatrice(grille, x, y, nouvelleValeur) {
    if (!grille || grille.length === 0) return grille;
    const lignes = grille.length;
    const colonnes = grille[0].length;
    if (x < 0 || x >= colonnes || y < 0 || y >= lignes) return grille;

    const cible = grille[y][x];
    if (cible === nouvelleValeur) return grille;

    const visite = new Set();
    const pile = [[x, y]];

    while (pile.length > 0) {
        const [cx, cy] = pile.pop();
        const clef = `${cx},${cy}`;
        if (visite.has(clef)) continue;
        if (cx < 0 || cx >= colonnes || cy < 0 || cy >= lignes) continue;
        if (grille[cy][cx] !== cible) continue;

        visite.add(clef);
        grille[cy][cx] = nouvelleValeur;

        pile.push([cx + 1, cy]);
        pile.push([cx - 1, cy]);
