function evaluerExpression(expr) {
  const tokens = expr.replace(/\s+/g, '').match(/(\d+\.?\d*|\+|\-|\*|\/|\(|\))/g) || [];

  let pos = 0;
  function peek() { return tokens[pos]; }
  function consume() { return tokens[pos++]; }

  function parseExpr() {
    let left = parseTerm();
    while (peek() === '+' || peek() === '-') {
      const op = consume();
      const right = parseTerm();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  function parseTerm() {
    let left = parseFactor();
    while (peek() === '*' || peek() === '/') {
      const op = consume();
      const right = parseFactor();
      left = op === '*' ? left * right : left / right;
    }
    return left;
  }

  function parseFactor() {
    if (peek() === '(') {
      consume();
      const val = parseExpr();
      consume(); // )
      return val;
    }
    return parseFloat(consume());
