function dijkstra(graphe, depart) {
  const distances = {};
  const settled = new Set();
  const allNodes = new Set(Object.keys(graphe));
  for (const k of Object.keys(graphe)) {
    for (const n of Object.keys(graphe[k])) allNodes.add(n);
  }

  for (const n of allNodes) distances[n] = Infinity;
  distances[depart] = 0;

  while (settled.size < allNodes.size) {
    let minNode = null;
    for (const n of allNodes) {
      if (!settled.has(n) && (minNode === null || distances[n] < distances[minNode])) {
        minNode = n;
      }
    }
    if (minNode === null || distances[minNode] === Infinity) break;
    settled.add(minNode);
    if (graphe[minNode]) {
      for (const [voisin, poids] of Object.entries(graphe[minNode])) {
        const d = distances[minNode] + poids;
        if (d < distances[voisin]) distances[voisin] = d;
      }
    }
  }

  return distances;
}
