      let num = '';
      while (i < expr.length && /\d/.test(expr[i])) num += expr[i++];
      tokens.push(parseInt(num, 10));
    } else if (ch === '(' || ch === ')') {
      tokens.push(ch);
      i++;
    } else {
      i++;
    }
  }

  function parseExpr(pos) {
    let left = parseTerm(pos);
    while (pos[0] < tokens.length && (tokens[pos[0]] === '+' || tokens[pos[0]] === '-')) {
      const op = tokens[pos[0]++];
      const right = parseTerm(pos);
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  function parseTerm(pos) {
    let left = parseFactor(pos);
    while (pos[0] < tokens.length && (tokens[pos[0]] === '*' || tokens[pos[0]] === '/')) {
      const op = tokens[pos[0]++];
      const right = parseFactor(pos);
      left = op === '*' ? left * right : left / right;
