function trier_tableau(arr) {
    // Tri par insertion - O(n²) mais sans utiliser .sort()
    const result = [...arr];
    for (let i = 1; i < result.length; i++) {
        const clef = result[i];
        let j = i - 1;
        while (j >= 0 && result[j] > clef) {
            result[j + 1] = result[j];
            j--;
        }
        result[j + 1] = clef;
    }
    return result;
}

