function medianeDeuxTries(a, b) {
    const n = a.length + b.length;
    const estPair = n % 2 === 0;
    const milieu = Math.floor(n / 2);

    let i = 0, j = 0;
    let actuel = 0, precedent = 0;
    let compteur = 0;

    while (i < a.length || j < b.length) {
        precedent = actuel;

        if (i < a.length && (j >= b.length || a[i] <= b[j])) {
            actuel = a[i];
            i++;
        } else {
            actuel = b[j];
            j++;
        }

        compteur++;

        if (compteur === milieu) {
            if (estPair) {
                return (precedent + actuel) / 2;
            } else {
                return actuel;
            }
        }

        if (compteur === milieu + 1 && estPair) {
            return (precedent + actuel) / 2;
        }
    }

    // Cas où un tableau est vide
    if (estPair) {
        return (precedent + actuel) / 2;
    }
    return actuel;
}

