function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;

    // Dynamic Programming avec optimisation O(N log N)
    // Utilisation de "patience sorting" / binary search
    const tails = [tab[0]];

    for (let i = 1; i < tab.length; i++) {
        const val = tab[i];

        if (val > tails[tails.length - 1]) {
            // Étendre la plus longue subsequence
            tails.push(val);
        } else {
            // Trouver la position avec binary search
            let gauche = 0;
            let droite = tails.length - 1;

            while (gauche < droite) {
                const milieu = Math.floor((gauche + droite) / 2);
                if (tails[milieu] < val) {
                    gauche = milieu + 1;
                } else {
                    droite = milieu;
                }
            }

            tails[gauche] = val;
        }
    }

    return tails.length;
}

