        const clef = triee[i];
        let j = i - 1;
        while (j >= 0 && triee[j][0] > clef[0]) {
            triee[j + 1] = triee[j];
            j--;
        }
        triee[j + 1] = clef;
    }

    // Fusionner les intervalles qui se chevauchent
    const resultat = [triee[0]];

    for (let i = 1; i < triee.length; i++) {
        const dernier = resultat[resultat.length - 1];
        const courant = triee[i];

        if (courant[0] <= dernier[1]) {
            // Chevauchement: étendre si nécessaire
            dernier[1] = Math.max(dernier[1], courant[1]);
        } else {
            // Pas de chevauchement: ajouter
            resultat.push(courant);
        }
    }

    return resultat;
}

// Tests
console.log(fusionnerIntervalles([[1, 3], [2, 6]]));          // [[1, 6]]
console.log(fusionnerIntervalles([[1, 4], [4, 5]]));          // [[1, 5]]
console.log(fusionnerIntervalles([[1, 4], [0, 4]]));          // [[0, 4]]
console.log(fusionnerIntervalles([[1, 4], [2, 3], [3, 9]]));  // [[1, 9]]

function prefixeCommun(tab) {
    if (tab.length === 0) return '';
    if (tab.length === 1) return tab[0];

    const premiere = tab[0];

    for (let i = 1; i < tab.length; i++) {
        const courant = tab[i];
        let j = 0;

        while (j < premiere.length && j < courant.length && 
               premiere[j] === courant[j]) {
            j++;
        }

        // Retourner le préfixe commun trouvé
        if (j === 0) return '';

        // Modifier la première chaîne pour le prochain tour
        // (efficacité: on garde juste le préfixe)
        tab[0] = premiere.substring(0, j);
    }

    return tab[0];
}

// Version alternative plus claire
function prefixeCommun(tab) {
    if (tab.length === 0) return '';

    let prefixe = tab[0];

    for (let i = 1; i < tab.length && prefixe.length > 0; i++) {
        while (tab[i].indexOf(prefixe) !== 0) {
            prefixe = prefixe.substring(0, prefixe.length - 1);
        }
    }

    return prefixe;
}

