console.log(prefixeCommun(["interview", "inter", "internal"])); // "inter"
console.log(prefixeCommun(["a"]));                              // "a"

function nombreDeBits1(n) {
    // Méthode de Brian Kernighan: O(k) où k = nombre de bits à 1
    let count = 0;

    while (n > 0) {
        n = n & (n - 1); // Élimine le bit 1 de droite le plus bas
        count++;
    }

    return count;
}

// Alternative: Division par 2
function nombreDeBits1_v2(n) {
    let count = 0;

    while (n > 0) {
        if (n % 2 === 1) count++;
        n = Math.floor(n / 2);
    }

    return count;
}

