console.log(plusLongueSousSuiteCroissante([0, 1, 0, 3, 2, 3]));             // 4
console.log(plusLongueSousSuiteCroissante([7, 7, 7, 7, 7, 7, 7]));          // 1
console.log(plusLongueSousSuiteCroissante([]));                              // 0
console.log(plusLongueSousSuiteCroissante([1, 2, 3, 4, 5]));                // 5
